// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0);
        vm.assume(depositAmount >= withdrawAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.addToBalance{value: depositAmount}();

        uint256 balBefore = address(c).balance;
        uint256 storedBefore = c.getBalance(actor);

        vm.prank(actor);
        c.withdrawBalance();

        uint256 balAfter = address(c).balance;
        uint256 storedAfter = c.getBalance(actor);

        assertTrue((balAfter == 0) == (storedAfter == 0));
    }
}
